function StoreFreeDiamond:RefreshData()
    printInfo("refresh")
    local cnt = #self.StoreData
    KTool.SetActive(self.itemCell.gameObject, false)
    --StoreUtils.ResizeContent(self.Content, cnt, self.itemCell.gameObject)
