    --end
    self._token = StoreShared.SettingStores[StoreConstants.OpenIds.StoreFreeDiamond].voData.token
    StoreShared:RefreshCurrency(self._token)
    
    if self._inited == nil then
        self.LoopView:InitGridView(cnt, Bind(self, self.OnRefreshIndex))
        self._inited = true
    else
        GameUtils.ReloadData(self.LoopView, cnt)
    end

end

function StoreFreeDiamond:GetBoardLabel(data)
    local corner,btm
    if data.price == 648 then
        return StoreConstants.FreeDiamondLabel.Sp, StoreConstants.FreeDiamondLabel.Sp
    else
        btm = StoreConstants.FreeDiamondLabel.Default
    end

    if data.isFirst == 1 then
        corner = StoreConstants.FreeDiamondLabel.Double
    else
        corner = StoreConstants.FreeDiamondLabel.Normal
    end
    
    return corner,btm
end

function StoreFreeDiamond:GetExtraNum(data)
    if data.isFirst == 1 then
        return data.num
    end
    return data.extraNum
end

function StoreFreeDiamond:GetNumPercentage(data)
    if data.isFirst == 1 then
        return 200
    end
    
    return CS.UnityEngine.Mathf.FloorToInt((data.num + data.extraNum) / data.num * 100)
end

function StoreFreeDiamond:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CellName)
    local data = self.StoreData[index + 1]
    self:RefreshCell(cell.transform, data, index + 1)
    return cell
end

function StoreFreeDiamond:RefreshCell(trans, data, index)
    if not KTool.IsActiveInHierarchy(trans.gameObject) then
        KTool.SetActive(trans.gameObject, true)
    end
    trans = trans:GetChild(0)
    
    local btn = trans.gameObject:GetComponent(typeof(ButtonComp))
    SetButtonAction(btn, function()
        local num = GoodsUtils.GetThingNo(data.currency)
        if data.price > num then
            StoreUtils.OpenRechargePopUp(data.price - num)
            return
        end
        UIModule.OpenDialog({ id = Constants.UITypeIds.StoreItemDetailsDialog, parameters = { OpenId = StoreConstants.OpenIds.StoreFreeDiamond, ItemData = data } })
    end)
    
    
    --StoreShared:LoadSpriteAsync
    local group = trans.gameObject:GetComponent(typeof(CanvasGroup))
    group.alpha = 0
    group:DOFade(1, StoreConstants.FadeInTime):SetDelay(StoreConstants.FadeDelay * index)
    
    
    --local corner, btm = self:GetBoardLabel(data)
    --local path = string.format(StoreConstants.FreeDiamondBtm, btm)
    --local image = trans:Find("btm").gameObject:GetComponent(typeof(ImageComp))
    --StoreShared:LoadSpriteAsync(image, path)
    --path = string.format(StoreConstants.FreeDiamondCorner, corner)
    local image = trans:Find("corner").gameObject:GetComponent(typeof(ImageComp))
    --StoreShared:LoadSpriteAsync(image, path)
    --local percentage = tostring(self:GetNumPercentage(data)) .. StoreConstants.PercentageStr
    --trans:Find("corner/Text").gameObject:GetComponent(typeof(TextComp)).text = percentage
    KTool.SetActive(image.gameObject, data.isFirst == 1)
    --path = GoodsConfMgr:GetInstance():GetPhotoPathById(data.currency)
    
    --printInfo(goodsId)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
    
    trans:Find("desc").gameObject:GetComponent(typeof(TextComp)).text = localize("兑换_goodsName_",{_goodsName_ = vo.name})
    trans:Find("num").gameObject:GetComponent(typeof(TextMeshProUGUI)).text = data.num

    local path = vo.photoPath
    image = trans:Find("currency"):GetComponent(typeof(ImageComp))
    StoreShared:LoadSpriteAsync(image, path)

    
    local extraNum = self:GetExtraNum(data)
    KTool.SetActive(trans:Find("empty").gameObject, extraNum == 0)
    KTool.SetActive(trans:Find("firstCoupon").gameObject, data.isFirst == 1)
    
    if extraNum == 0 then
        KTool.SetActive(trans:Find("extraDesc").gameObject, false)
        KTool.SetActive(trans:Find("extraNumNode").gameObject, false)
    else
        KTool.SetActive(trans:Find("extraDesc").gameObject, true)
        KTool.SetActive(trans:Find("extraNumNode").gameObject, true)
        trans:Find("extraNumNode"):Find("extraNum").gameObject:GetComponent(typeof(TextMeshProUGUI)).text = extraNum
    end

    path = GoodsConfMgr:GetInstance():GetPhotoPathById(data.currency)
    image = trans:Find("priceIcon"):GetComponent(typeof(ImageComp))
    StoreShared:LoadSpriteAsync(image, path)

    local showId = checkNumber(data.icon) == 0 and data.goodsId or checkNumber(data.icon)
    local showVo = GoodsConfMgr:GetInstance():GetGoodsVoById(showId)
    path = showVo.photoPath
    image = trans:Find("icon").gameObject:GetComponent(typeof(ImageComp))
    StoreShared:LoadSpriteAsync(image, path)
    trans:Find("extraNumNode"):Find("TextDesc").gameObject:GetComponent(typeof(TextComp)).text = showVo.name
    trans:Find("price").gameObject:GetComponent(typeof(TextMeshProUGUI)).text = data.price
    
    
end

